using BusinessOS.Pharmacy.Persistence.Entities;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace BusinessOS.Pharmacy.Persistence.Configurations;internal sealed class DailyClosingEventConfiguration:IEntityTypeConfiguration<DailyClosingEventEntity>{public void Configure(EntityTypeBuilder<DailyClosingEventEntity>b){b.ToTable("daily_closing_events");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id").HasMaxLength(36).ValueGeneratedNever();b.Property(x=>x.DailyClosingId).HasColumnName("daily_closing_id").HasMaxLength(36).IsRequired();b.Property(x=>x.EventType).HasColumnName("event_type").HasMaxLength(40).IsRequired();b.Property(x=>x.ActorId).HasColumnName("actor_id").HasMaxLength(64);b.Property(x=>x.Reason).HasColumnName("reason").HasMaxLength(2000);b.Property(x=>x.SnapshotJson).HasColumnName("snapshot");b.Property(x=>x.OccurredAt).HasColumnName("occurred_at").IsRequired();b.Property(x=>x.CreatedAt).HasColumnName("created_at").IsRequired();b.Property(x=>x.UpdatedAt).HasColumnName("updated_at").IsRequired();b.HasIndex(x=>x.EventType);b.HasIndex(x=>x.OccurredAt);b.HasOne(x=>x.Closing).WithMany(x=>x.Events).HasForeignKey(x=>x.DailyClosingId).OnDelete(DeleteBehavior.Cascade);}}
